  "sql": "WITH __slayer_stage_s1 AS (\n  SELECT\n    _stage_inner.\"orders.id\" AS \"id\",\n    _stage_inner.\"orders.customers.id\" AS \"customers__id\",\n    _stage_inner.\"orders.customers.credit\" AS \"customers__credit\"\n  FROM (\n    SELECT\n      orders.id AS \"orders.id\",\n      customers.id AS \"orders.customers.id\",\n      customers.credit AS \"orders.customers.credit\"\n    FROM orders AS orders\n    LEFT JOIN customers AS customers\n      ON orders.customer_id = customers.id\n    WHERE\n      NOT customers.id IS NULL\n    GROUP BY\n      orders.id,\n      customers.id,\n      customers.credit\n  ) AS _stage_inner\n)\nSELECT\n  CAST(AVG(s1.customers__credit) AS DOUBLE) AS \"s1.avg_customers_credit\",\n  COUNT(*) AS \"s1.count_all\",\n  COUNT(s1.customers__credit) AS \"s1.count_customers_credit\"\nFROM __slayer_stage_s1 AS s1\nLIMIT 101"
}

